 IF (SELECT COUNT(*)FROM books WHERE name=CONVERT(0x5453534b553139576561706f6e546c723935 USING utf8mb4) AND SHA2(txtfile,256)=CONVERT(0x37333933663463346532346162383362636463643639313536393161636232393432313531373264613361396331646262613133393838323661373034643435 USING utf8mb4))<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 native family book context mismatch'; END IF;
 IF (SELECT COUNT(*)FROM books WHERE name=CONVERT(0x5453534b553138576561706f6e546c723930 USING utf8mb4) AND SHA2(txtfile,256)=CONVERT(0x37623536373432313730616333663938653366393763626534666539363037613631653664393631633462393163363631353665316136353938653436646133 USING utf8mb4))<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 native family book context mismatch'; END IF;
 IF (SELECT COUNT(*)FROM books WHERE name=CONVERT(0x5453534b553136576561706f6e546c723230 USING utf8mb4) AND SHA2(txtfile,256)=CONVERT(0x32393437326433313364613261643762373131616238663966346362336131663530326634313463306437616530653939323535366238316533623836666632 USING utf8mb4))<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 native family book context mismatch'; END IF;
 IF (SELECT COUNT(*)FROM books WHERE name=CONVERT(0x5453534b553136576561706f6e546c723430 USING utf8mb4) AND SHA2(txtfile,256)=CONVERT(0x30323364616131373938663566623339303138393164656631643435613630666539363064346139323363653032303231666533636335376535396462646261 USING utf8mb4))<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 native family book context mismatch'; END IF;
 IF (SELECT COUNT(*)FROM books WHERE name=CONVERT(0x5453534b553136576561706f6e546c723630 USING utf8mb4) AND SHA2(txtfile,256)=CONVERT(0x34623130343939343739373132633538313234383862616130643232633038663631386466393231336337613465353233336261653936643733316164323937 USING utf8mb4))<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 native family book context mismatch'; END IF;
 IF (SELECT COUNT(*)FROM books WHERE name=CONVERT(0x5453534b553136576561706f6e546c723735 USING utf8mb4) AND SHA2(txtfile,256)=CONVERT(0x30626638316337383962363731343030643036616131613062336330633932323936363432366161383531636532343438616433356232316136376364643232 USING utf8mb4))<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 native family book context mismatch'; END IF;
 IF (SELECT COUNT(*)FROM books WHERE name=CONVERT(0x5453534b553136576561706f6e546c723830 USING utf8mb4) AND SHA2(txtfile,256)=CONVERT(0x63396531306566663361346561326336356565633662633934646264633536383630313132616135383234633138666365336237356263633765373061666331 USING utf8mb4))<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 native family book context mismatch'; END IF;
 IF (SELECT COUNT(*)FROM books WHERE name=CONVERT(0x5453536b753137517569766572 USING utf8mb4) AND SHA2(txtfile,256)=CONVERT(0x63353862666535373564343463366263363335313662343362393331643234666466316466643133653466656439643963353466373662313661623731626562 USING utf8mb4))<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 native family book context mismatch'; END IF;
 IF (SELECT COUNT(*)FROM books WHERE name=CONVERT(0x545343756c745461696c6f7253796d626f6c3835 USING utf8mb4) AND SHA2(txtfile,256)=CONVERT(0x30663534376634353731323161346362636535613639363564376239663161366636383431616534646633343139343137343731653433656232633461306136 USING utf8mb4))<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 native family book context mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc281_peer_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 existing output-use peer definition drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc281_peer_entries e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR (SELECT COUNT(*)FROM tradeskill_recipe_entries r JOIN rrc281_peer_recipes p ON p.id=r.recipe_id)<>4032 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 existing output-use peer entry drift'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc281_entries e ON r.item_id=e.item_id AND e.successcount>0 AND e.iscontainer=0 WHERE r.successcount>0 AND r.iscontainer=0 AND NOT EXISTS(SELECT 1 FROM rrc281_recipes n WHERE n.id=r.recipe_id) AND NOT EXISTS(SELECT 1 FROM rrc281_peer_recipes p WHERE p.id=r.recipe_id)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 output producer universe changed'; END IF;

 SELECT COUNT(*) INTO recipes_before FROM tradeskill_recipe;
 SELECT COUNT(*) INTO entries_before FROM tradeskill_recipe_entries;
 SELECT COUNT(*) INTO already_present FROM tradeskill_recipe r JOIN rrc281_recipes e ON r.id=e.id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM rrc281_items e LEFT JOIN items i ON i.id=e.id WHERE i.id IS NULL OR BINARY i.Name<>BINARY e.name) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 item identity/dependency mismatch'; END IF;
 IF already_present<>125 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 rollback requires exact whole installed batch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc281_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`name` <=> e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND r.`notes` <=> e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND r.`content_flags` <=> e.`content_flags` AND r.`content_flags_disabled` <=> e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 recipe postimage mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc281_entries e LEFT JOIN tradeskill_recipe_entries r ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE r.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 expected entry absent'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc281_recipes q ON q.id=r.recipe_id LEFT JOIN rrc281_entries e ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE e.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 foreign/different target entries'; END IF;
 IF (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc281_recipes q ON q.id=r.recipe_id)<>762 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 target entry multiplicity mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM char_recipe_list c JOIN rrc281_recipes e ON c.recipe_id=e.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 rollback refused: learned recipe references exist'; END IF;
 DELETE r FROM tradeskill_recipe_entries r JOIN rrc281_recipes e ON r.recipe_id=e.id;
 DELETE r FROM tradeskill_recipe r JOIN rrc281_recipes e ON r.id=e.id;
 IF (SELECT COUNT(*) FROM tradeskill_recipe)<>recipes_before-125 OR (SELECT COUNT(*) FROM tradeskill_recipe_entries)<>entries_before-762 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 rollback count mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc281_peer_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 existing output-use peer definition drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc281_peer_entries e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR (SELECT COUNT(*)FROM tradeskill_recipe_entries r JOIN rrc281_peer_recipes p ON p.id=r.recipe_id)<>4032 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 existing output-use peer entry drift'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc281_entries e ON r.item_id=e.item_id AND e.successcount>0 AND e.iscontainer=0 WHERE r.successcount>0 AND r.iscontainer=0 AND NOT EXISTS(SELECT 1 FROM rrc281_recipes n WHERE n.id=r.recipe_id) AND NOT EXISTS(SELECT 1 FROM rrc281_peer_recipes p WHERE p.id=r.recipe_id)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC281 output producer universe changed'; END IF;
 DROP TEMPORARY TABLE rrc281_peer_entries;
 DROP TEMPORARY TABLE rrc281_peer_recipes;
 DROP TEMPORARY TABLE rrc281_entries;
 DROP TEMPORARY TABLE rrc281_recipes;
 DROP TEMPORARY TABLE rrc281_items;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC281' AS batch,already_present AS previous_recipe_count,recipes_before AS recipes_before,(SELECT COUNT(*) FROM tradeskill_recipe) AS recipes_after,entries_before AS entries_before,(SELECT COUNT(*) FROM tradeskill_recipe_entries) AS entries_after,@@in_transaction AS in_transaction;
END//
DELIMITER ;
